parameters.jsonBody:
{"query": "query RecentArtBlocksProjects {
  projects_metadata(
    where: {chain_id: {_eq: 1}, active: {_eq: true}, activated_at: {_is_null: false}}
    order_by: [{activated_at: desc}, {id: asc}]
    limit: 20
  ) { id chain_id name activated_at invocations max_invocations }
}"}

parameters.jsCode:
const body = $input.first().json.data;
if (typeof body !== 'string' || Buffer.byteLength(body) > 65536) throw Error('Invalid response size');
const response = JSON.parse(body);
const rows = response.data?.projects_metadata;
if (response.errors || !Array.isArray(rows) || rows.length === 0 || rows.length > 20)
  throw Error('Missing or partial project data');
const seen = new Set();
const now = new Date();
for (const row of rows) {
  const count = value => (Number.isSafeInteger(value) && value >= 0) ||
    (typeof value === 'string' && /^(0|[1-9][0-9]{0,14})$/.test(value));
  if (!row || row.chain_id !== 1 || !/^0x[0-9a-f]{40}-[0-9]+$/i.test(row.id) ||
      seen.has(row.id.toLowerCase()) || typeof row.name !== 'string' ||
      !row.name.trim() || row.name.length > 512 || !count(row.invocations) ||
      !count(row.max_invocations) || Number(row.invocations) > Number(row.max_invocations) ||
      typeof row.activated_at !== 'string' || !Number.isFinite(Date.parse(row.activated_at)) ||
      Date.parse(row.activated_at) > now.getTime()) throw Error('Invalid project observation');
  seen.add(row.id.toLowerCase());
}
const slot = new Date(Math.floor(now.getTime() / 21600000) * 21600000).toISOString();
return [{json: {body, slot, observed: now.toISOString(), size: rows.length},
  binary: {data: {data: Buffer.from(body, 'utf8').toString('base64'),
    mimeType: 'application/json', fileName: 'response.json'}}}];

const write = $('Record observation').first().json;
const observed = $('Fingerprint response').first().json;
const accepted = $input.first().json.accepted;
if (!['inserted','slot_already_recorded'].includes(write.outcome) || !accepted?.id ||
    !/^[a-f0-9]{64}$/.test(accepted.sha)) throw Error('Unverified DB receipt');
if (write.outcome === 'inserted' && (write.new_id !== accepted.id || accepted.sha !== observed.sha))
  throw Error('Readback mismatch');
return [{json: {outcome:write.outcome, acceptedId:accepted.id, acceptedSourceHash:accepted.sha,
  observedSourceHash:observed.sha, sameEvidence:observed.sha === accepted.sha,
  slot:observed.slot, runRef:'n8n:'+$execution.id, originalRunRef:accepted.run_ref}}];
